import React from 'react';
import './Menu.css';

const Menu = () => {
  const menuItems = [
    {
      id: 1,
      name: 'Kofta',
      price: 250,
      description: "Soft, spicy koftas soaking in rich, creamy gravy — a bite of pure bliss in every spoonful.",
      veg: true
    },
    {
      id: 2,
      name: 'Samosha',
      price: 180,
      description: "Crispy outside, spicy inside — a samosa is not just a snack, it's an emotion wrapped in crunch.",
      veg: true
    },
    {
      id: 3,
      name: 'Rogan Josh',
      price: 280,
      description: 'Aromatic lamb curry from Kashmir',
      veg: false
    }
  ];

  return (
    <div className="menu-container">
      <h1>Hotel Shyam Special Menu</h1>
      <p className="subtitle">Authentic flavors crafted with traditional recipes</p>

      <div className="menu-items">
        {menuItems.map(item => (
          <div key={item.id} className="menu-item">
            <div className="item-header">
              <h3>{item.name}</h3>
              <span className={`veg-tag ${item.veg ? 'veg' : 'non-veg'}`}>
                {item.veg ? '🟢 VEG' : '🔴 NON-VEG'}
              </span>
            </div>
            <p className="item-desc">{item.description}</p>
            <div className="item-footer">
              <span className="price">₹{item.price}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Menu;
